functions.setThing:
{
   if(target.type == "宝石")
   {
      if(this.stone1.type == "空格")
      {
         this.stone1.setThing(target);
      }
      else
      {
         if(!(this.stone2.type == "空格" && (target.type == this.stone1.type || this.stone1.name == "高级战斗力宝石" || this.stone2.name == "高级战斗力宝石")))
         {
            return false;
         }
         this.stone2.setThing(target);
      }
      this.flashInfo();
      return true;
   }
   return false;
}

functions.flashInfo:
{
   if(this.stone1.type == "空格" || this.stone2.type == "空格")
   {
      this.info.text = "  可以将两个同种类的高级宝石融合出属性值更高的宝石。其中高级战斗力宝石可以和任一种高级宝石融合。";
      return false;
   }
   switch(this.stone1.name)
   {
      case "高级战斗力宝石":
         if(this.stone2.name == "高级战斗力宝石")
         {
            if(this.stone1.val1 < 8)
            {
               this.info.text = "可以融合得到高级战斗力宝石";
            }
            else if(this.stone1.val1 < 15)
            {
               this.info.text = "可以融合得到高级战斗力宝石，需要消耗声望" + (this.stone1.val1 - 6);
            }
            else
            {
               this.info.text = "主宝石的属性已经最高，不能再融合了";
            }
         }
         else if(this.stone2.name == "高级攻击宝石" || this.stone2.name == "高级减伤害宝石" || this.stone2.name == "高级经验宝石")
         {
            this.info.text = "可以融合得到圣石";
         }
         else
         {
            this.info.text = "不可以融合，只有高级宝石才能融合。";
         }
         return;
      case "高级攻击宝石":
         if(this.stone2.name == "高级攻击宝石")
         {
            if(this.stone1.val1 < 25)
            {
               this.info.text = "可以融合得到高级攻击宝石";
            }
            else
            {
               this.info.text = "主宝石的属性已经最高，不能再融合了";
            }
         }
         else if(this.stone2.name == "高级战斗力宝石")
         {
            this.info.text = "可以融合得到战斗攻击圣石";
         }
         else
         {
            this.info.text = "不可以融合，只有高级宝石才能融合。";
         }
         return;
      case "高级减伤害宝石":
         if(this.stone2.name == "高级减伤害宝石")
         {
            if(this.stone1.val1 < 13)
            {
               this.info.text = "可以融合得到高级减伤害宝石";
            }
            else
            {
               this.info.text = "主宝石的属性已经最高，不能再融合了";
            }
         }
         else if(this.stone2.name == "高级战斗力宝石")
         {
            this.info.text = "可以融合得到战斗减伤害圣石";
         }
         else
         {
            this.info.text = "不可以融合，只有高级宝石才能融合。";
         }
         return;
      case "高级经验宝石":
         if(this.stone2.name == "高级经验宝石")
         {
            if(this.stone1.val1 < 35)
            {
               this.info.text = "可以融合得到高级经验宝石";
            }
            else
            {
               this.info.text = "主宝石的属性已经最高，不能再融合了";
            }
         }
         else if(this.stone2.name == "高级战斗力宝石")
         {
            this.info.text = "可以融合得到战斗经验圣石";
         }
         else
         {
            this.info.text = "不可以融合，只有高级宝石才能融合。";
         }
         return;
      default:
         this.info.text = "不可以融合";
         return;
   }
}

functions.beginRefine:
{
   if(this.stone1.type == "空格" || this.stone2.type == "空格")
   {
      return false;
   }
   switch(this.stone1.name)
   {
      case "高级战斗力宝石":
         if(this.stone2.name == "高级战斗力宝石")
         {
            if(this.stone1.val1 < 8)
            {
               this.stone1.setThing({type:"宝石",name:"高级战斗力宝石",val1:this.stone1.val1 + 1,salePrice:2000});
               this.stone2.setThing({type:"空格"});
               return true;
            }
            if(this.stone1.val1 < 15 && _root.map.role.xxx_credit >= this.stone1.val1 - 6)
            {
               _root.map.role.xxx_credit -= this.stone1.val1 - 6;
               _global.sysMsg.addMsg("声望 -" + (this.stone1.val1 - 6));
               this.stone1.setThing({type:"宝石",name:"高级战斗力宝石",val1:this.stone1.val1 + 1,salePrice:2000});
               this.stone2.setThing({type:"空格"});
               return true;
            }
            return false;
         }
         if(this.stone2.name == "高级攻击宝石" || this.stone2.name == "高级减伤害宝石" || this.stone2.name == "高级经验宝石")
         {
            switch(this.stone2.name)
            {
               case "高级攻击宝石":
                  this.stone1.setThing({type:"宝石",name:"战斗攻击圣石",val1:this.stone1.val1,val2:this.stone2.val1,salePrice:3000});
                  break;
               case "高级减伤害宝石":
                  this.stone1.setThing({type:"宝石",name:"战斗减伤害圣石",val1:this.stone1.val1,val2:this.stone2.val1,salePrice:3000});
                  break;
               case "高级经验宝石":
                  this.stone1.setThing({type:"宝石",name:"战斗经验圣石",val1:this.stone1.val1,val2:this.stone2.val1,salePrice:3000});
            }
            this.stone2.setThing({type:"空格"});
            return true;
         }
         return false;
         break;
      case "高级攻击宝石":
         if(this.stone2.name == "高级攻击宝石")
         {
            if(this.stone1.val1 < 25)
            {
               this.stone1.setThing({type:"宝石",name:"高级攻击宝石",val1:this.stone1.val1 + 2,salePrice:1000});
               this.stone2.setThing({type:"空格"});
               return true;
            }
            return false;
         }
         if(this.stone2.name == "高级战斗力宝石")
         {
            this.stone1.setThing({type:"宝石",name:"战斗攻击圣石",val1:this.stone2.val1,val2:this.stone1.val1,salePrice:3000});
            this.stone2.setThing({type:"空格"});
            return true;
         }
         return false;
         break;
      case "高级减伤害宝石":
         if(this.stone2.name == "高级减伤害宝石")
         {
            if(this.stone1.val1 < 13)
            {
               this.stone1.setThing({type:"宝石",name:"高级减伤害宝石",val1:this.stone1.val1 + 1,salePrice:1000});
               this.stone2.setThing({type:"空格"});
               return true;
            }
            return false;
         }
         if(this.stone2.name == "高级战斗力宝石")
         {
            this.stone1.setThing({type:"宝石",name:"战斗减伤害圣石",val1:this.stone2.val1,val2:this.stone1.val1,salePrice:3000});
            this.stone2.setThing({type:"空格"});
            return true;
         }
         return false;
         break;
      case "高级经验宝石":
         if(this.stone2.name == "高级经验宝石")
         {
            if(this.stone1.val1 < 35)
            {
               this.stone1.setThing({type:"宝石",name:"高级经验宝石",val1:this.stone1.val1 + 2,salePrice:1000});
               this.stone2.setThing({type:"空格"});
               return true;
            }
            return false;
         }
         if(this.stone2.name == "高级战斗力宝石")
         {
            this.stone1.setThing({type:"宝石",name:"战斗经验圣石",val1:this.stone2.val1,val2:this.stone1.val1,salePrice:3000});
            this.stone2.setThing({type:"空格"});
            return true;
         }
         return false;
         break;
      default:
         return false;
   }
}

functions.yesButton.onRelease:
{
   if(this._parent.beginRefine() == true)
   {
      _global.playSound("精练成功.wav");
      _global.sysMsg.addMsg("宝石融合成功");
   }
   this._parent.flashInfo();
}
